package app.repositories

import app.RefusedException
import app.Sql
import app.common.Page
import app.entities.Category
import app.errors.ConflictException
import java.sql.Connection
import java.sql.ResultSet

/** Keeps categories rows in the database, with SQL through JDBC. A write joins the transaction already open, or is committed at once. */
class SqlCategoryRepository(private val connection: Connection) : CategoryRepository {
    /** The columns every read selects. */
    private val columns = "\"id\", \"name\""

    override fun findById(id: Int): Category? {
        return Sql.one(connection, "SELECT " + columns + " FROM \"categories\" WHERE \"id\" = ?", id) { toEntity(it) }
    }

    override fun list(offset: Int, limit: Int): Page<Category> {
        val items = Sql.all(connection, "SELECT " + columns + " FROM \"categories\" ORDER BY \"id\" LIMIT ? OFFSET ?", limit, offset) { toEntity(it) }
        val total = Sql.one(connection, "SELECT COUNT(*) FROM \"categories\"") { it.getLong(1) } ?: 0L
        return Page(items, total, offset, limit)
    }

    override fun findByName(name: String): Category? {
        return Sql.one(connection, "SELECT " + columns + " FROM \"categories\" WHERE \"name\" = ?", name) { toEntity(it) }
    }

    override fun insert(entity: Category): Category {
        val given = listOf<Pair<String, Any?>>(
            "\"id\"" to entity.id,
            "\"name\"" to entity.name,
        ).filter { it.second != null }
        val values = given.map { it.second }.toTypedArray()
        val sql =
            if (given.isEmpty()) "INSERT INTO \"categories\" DEFAULT VALUES"
            else "INSERT INTO \"categories\" (" + given.joinToString(", ") { it.first } + ") VALUES (" + given.joinToString(", ") { "?" } + ")"
        return write { Sql.one(connection, sql + " RETURNING " + columns, *values) { fill(it, entity) } }
            ?: error("The Category just written is not there")
    }

    override fun update(entity: Category): Category {
        write { Sql.run(connection, "UPDATE \"categories\" SET \"name\" = ? WHERE \"id\" = ?", entity.name, entity.id) }
        return Sql.one(connection, "SELECT " + columns + " FROM \"categories\" WHERE \"id\" = ?", entity.id) { fill(it, entity) }
            ?: error("The Category just written is not there")
    }

    override fun delete(entity: Category): Unit {
        write { Sql.run(connection, "DELETE FROM \"categories\" WHERE \"id\" = ?", entity.id) }
    }

    private fun toEntity(row: ResultSet): Category = fill(row, Category())

    /** Reads a row selected with the columns into entity. */
    private fun fill(row: ResultSet, entity: Category): Category {
        entity.id = row.getInt(1).takeUnless { row.wasNull() }
        entity.name = row.getString(2)
        return entity
    }

    /** Runs a write; a database refusal (a unique value, a row still pointed to) becomes a ConflictException. */
    private fun <T> write(work: () -> T): T =
        try {
            work()
        } catch (error: RefusedException) {
            throw ConflictException("Category", "the database refused the change: ${error.message}")
        }
}

