package app

import app.entities.Category
import app.entities.Customer
import app.entities.Product
import app.entities.ProductTag
import app.entities.Tag
import java.math.BigDecimal

/** Rows for the tests: valid values for every column, and the rows they point to. */
object Factories {
    /** A valid Customer that is not stored yet; n makes its unique values differ. */
    fun newCustomer(n: Int): Customer =
        Customer(
            email = "email-$n",
            passwordHash = "passwordhash-$n",
        )

    /** A stored Customer. */
    fun addCustomer(uow: UnitOfWork, n: Int): Customer {
        val entity = newCustomer(n)
        return uow.customers.insert(entity)
    }

    /** A valid Category that is not stored yet; n makes its unique values differ. */
    fun newCategory(n: Int): Category =
        Category(
            name = "name-$n",
        )

    /** A stored Category. */
    fun addCategory(uow: UnitOfWork, n: Int): Category {
        val entity = newCategory(n)
        return uow.categories.insert(entity)
    }

    /** A valid Product that is not stored yet; n makes its unique values differ. */
    fun newProduct(n: Int): Product =
        Product(
            name = "name-$n",
            price = BigDecimal("${n % 10000}.50"),
            status = "draft",
        )

    /** A stored Product, with the rows it points to. */
    fun addProduct(uow: UnitOfWork, n: Int): Product {
        val parent0 = addCategory(uow, n)
        val entity = newProduct(n)
        entity.categoryId = parent0.id
        return uow.products.insert(entity)
    }

    /** A valid Tag that is not stored yet; n makes its unique values differ. */
    fun newTag(n: Int): Tag =
        Tag(
            label = "label-$n",
        )

    /** A stored Tag. */
    fun addTag(uow: UnitOfWork, n: Int): Tag {
        val entity = newTag(n)
        return uow.tags.insert(entity)
    }

    /** A valid ProductTag that is not stored yet; n makes its unique values differ. */
    fun newProductTag(n: Int): ProductTag =
        ProductTag(
        )

    /** A stored ProductTag, with the rows it points to. */
    fun addProductTag(uow: UnitOfWork, n: Int): ProductTag {
        val parent0 = addProduct(uow, n)
        val parent1 = addTag(uow, n)
        val entity = newProductTag(n)
        entity.productId = parent0.id
        entity.tagId = parent1.id
        return uow.productTags.insert(entity)
    }
}

