    @Test
    fun saysWhenARowIsMissing() {
        val service = TagService(uow)
        assertFailsWith<NotFoundException> { service.getTag(999999) }
    }

    @Test
    fun changesARow() {
        val service = TagService(uow)
        val row = Factories.newTag(1)
        val created = service.createTag(createOf(row))
        val updated = service.updateTag(created.id, TagUpdate(label = Patch.of("changed")))
        assertEquals("changed", updated.label)
    }

    @Test
    fun deletesARow() {
        val service = TagService(uow)
        val row = Factories.newTag(1)
        val created = service.createTag(createOf(row))
        service.deleteTag(created.id)
        assertFailsWith<NotFoundException> { service.getTag(created.id) }
    }

    /** The create DTO of a row the factories made. */
    private fun createOf(row: Tag) = TagCreate(
        label = row.label,
    )
}

